import{_ as t,o as a,c as o,a2 as i}from"./chunks/framework.BXzK3EA4.js";const r="/assets/image%20(126).CzlE05Yk.png",u=JSON.parse('{"title":"Themes","description":"Tradeboard Themes","frontmatter":{"description":"Tradeboard Themes"},"headers":[],"relativePath":"installation-guidelines/themes.md","filePath":"installation-guidelines/themes.md"}'),s={name:"installation-guidelines/themes.md"};function n(d,e,l,h,c,p){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="themes" tabindex="-1">Themes <a class="header-anchor" href="#themes" aria-label="Permalink to &quot;Themes&quot;">​</a></h1><p>Tradeboard&#39;s React frontend ships a two-axis theming system: a light or dark <strong>mode</strong>, combined with an <strong>accent colour</strong>. Analyzer mode overrides both with its own locked purple palette so you can always tell test mode from live trading at a glance.</p><figure><img src="'+r+`" alt=""><figcaption></figcaption></figure><h3 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h3><ul><li><strong>Two modes</strong>: Light and Dark</li><li><strong>Eight accent colours</strong>: applied on top of either mode</li><li><strong>Mode-specific theming</strong>: Analyzer mode has a fixed purple palette that cannot be changed</li><li><strong>Instant switching</strong>: theme changes apply immediately, with no page reload</li><li><strong>Persistent preferences</strong>: your choice is stored in the browser and restored on the next visit</li><li><strong>Responsive design</strong>: every combination works on desktop, tablet and mobile</li><li><strong>Accessibility</strong>: colours are defined in the OKLCH colour space with contrast-checked foreground pairings</li></ul><h3 id="available-themes" tabindex="-1">Available Themes <a class="header-anchor" href="#available-themes" aria-label="Permalink to &quot;Available Themes&quot;">​</a></h3><h4 id="modes" tabindex="-1">Modes <a class="header-anchor" href="#modes" aria-label="Permalink to &quot;Modes&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Mode</th><th>Description</th></tr></thead><tbody><tr><td><strong>Light</strong></td><td>Default bright interface</td></tr><tr><td><strong>Dark</strong></td><td>Reduced eye strain for extended trading sessions</td></tr></tbody></table><h4 id="accent-colours" tabindex="-1">Accent colours <a class="header-anchor" href="#accent-colours" aria-label="Permalink to &quot;Accent colours&quot;">​</a></h4><p>The accent colour drives the <code>--primary</code> and <code>--ring</code> tokens: buttons, links, active states and focus rings.</p><table tabindex="0"><thead><tr><th>Accent</th><th>Notes</th></tr></thead><tbody><tr><td><strong>Zinc</strong></td><td>Default. No override applied.</td></tr><tr><td><strong>Slate</strong></td><td>Subtle blue-grey</td></tr><tr><td><strong>Gray</strong></td><td>Pure neutral grey</td></tr><tr><td><strong>Neutral</strong></td><td>Warm grey</td></tr><tr><td><strong>Green</strong></td><td></td></tr><tr><td><strong>Blue</strong></td><td></td></tr><tr><td><strong>Violet</strong></td><td></td></tr><tr><td><strong>Orange</strong></td><td></td></tr></tbody></table><p>Each accent has a separate value for light and dark mode, so the same choice stays legible in both.</p><h3 id="theme-usage" tabindex="-1">Theme Usage <a class="header-anchor" href="#theme-usage" aria-label="Permalink to &quot;Theme Usage&quot;">​</a></h3><h4 id="live-mode-production-trading" tabindex="-1">Live Mode (production trading) <a class="header-anchor" href="#live-mode-production-trading" aria-label="Permalink to &quot;Live Mode (production trading)&quot;">​</a></h4><p>In Live Mode both axes are yours to set: either mode, any of the eight accents.</p><p><strong>Quick toggle (navbar)</strong></p><p>The navigation bar carries a sun/moon button that flips between Light and Dark instantly.</p><p><strong>Full selection (Profile page)</strong></p><ol><li>Open the profile menu and go to <strong>Profile</strong></li><li>Select the <strong>Theme</strong> tab</li><li>Pick a mode, then pick an accent colour</li><li>Both apply immediately and are saved automatically</li></ol><h4 id="analyzer-mode-sandbox-environment" tabindex="-1">Analyzer Mode (sandbox environment) <a class="header-anchor" href="#analyzer-mode-sandbox-environment" aria-label="Permalink to &quot;Analyzer Mode (sandbox environment)&quot;">​</a></h4><p><strong>Analyzer Mode</strong> is the risk-free environment for validating strategies and API requests without sending real orders.</p><p><strong>Fixed purple theme</strong></p><p>When you enter Analyzer Mode:</p><ul><li><strong>Auto-switch</strong>: the <code>analyzer</code> class is applied to the document root, replacing the palette with a dark purple scheme</li><li><strong>Visual indicator</strong>: the distinctive purple interface signals that no real orders are being placed</li><li><strong>Locked theme</strong>: mode and accent changes are ignored while Analyzer Mode is active</li><li><strong>Safety feature</strong>: you always know whether you are in test mode or live trading</li></ul><p><strong>Why a fixed theme?</strong></p><ol><li><strong>Visual confirmation</strong>: instantly recognise you are in test mode</li><li><strong>Prevent confusion</strong>: no mistaking Analyzer Mode for Live Mode</li><li><strong>Consistent experience</strong>: every user sees the same interface in documentation and support threads</li><li><strong>Safety first</strong>: a clear visual distinction reduces the risk of accidental live trading</li></ol><p><strong>Returning to Live Mode</strong></p><p>When you leave Analyzer Mode, your saved light or dark mode and accent colour are restored and theme switching becomes available again.</p><h3 id="how-to-change-themes" tabindex="-1">How to change themes <a class="header-anchor" href="#how-to-change-themes" aria-label="Permalink to &quot;How to change themes&quot;">​</a></h3><h4 id="method-1-quick-toggle-navbar" tabindex="-1">Method 1: quick toggle (navbar) <a class="header-anchor" href="#method-1-quick-toggle-navbar" aria-label="Permalink to &quot;Method 1: quick toggle (navbar)&quot;">​</a></h4><ol><li>Click the sun/moon icon in the navigation bar</li><li>The interface switches between Light and Dark instantly</li></ol><p><strong>Best for</strong>: quick switching at different times of day</p><h4 id="method-2-full-selection-profile-page" tabindex="-1">Method 2: full selection (Profile page) <a class="header-anchor" href="#method-2-full-selection-profile-page" aria-label="Permalink to &quot;Method 2: full selection (Profile page)&quot;">​</a></h4><ol><li>Open the profile menu and select <strong>Profile</strong></li><li>Go to the <strong>Theme</strong> tab</li><li>Choose Light or Dark, then choose an accent colour</li><li>The current selection is highlighted</li></ol><p><strong>Best for</strong>: setting the accent colour, which the navbar toggle does not cover</p><h3 id="technical-details" tabindex="-1">Technical details <a class="header-anchor" href="#technical-details" aria-label="Permalink to &quot;Technical details&quot;">​</a></h3><h4 id="technology-stack" tabindex="-1">Technology stack <a class="header-anchor" href="#technology-stack" aria-label="Permalink to &quot;Technology stack&quot;">​</a></h4><p>The frontend lives in <code>frontend/</code> and is a Vite + React application:</p><ul><li><strong>Tailwind CSS 4</strong> via <code>@tailwindcss/vite</code>, with the theme tokens declared in <code>frontend/src/index.css</code></li><li><strong>Radix UI</strong> primitives for the accessible component layer</li><li><strong>Zustand</strong> with its <code>persist</code> middleware for the theme store, at <code>frontend/src/stores/themeStore.ts</code></li></ul><p>DaisyUI is no longer part of Tradeboard&#39;s theming. Guides that reference a <code>tailwind.config.mjs</code>, a <code>static/js/theme.js</code>, <code>npm run build:css</code>, or a list of 30 DaisyUI theme names describe an older build and no longer apply.</p><h4 id="theme-implementation" tabindex="-1">Theme implementation <a class="header-anchor" href="#theme-implementation" aria-label="Permalink to &quot;Theme implementation&quot;">​</a></h4><p>Themes are pure CSS custom properties. Two independent hooks drive them:</p><div class="language-html vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">&lt;!-- Dark mode is a class on the root element --&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">html</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> class</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;dark&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> data-theme</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;blue&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">&lt;!-- Analyzer mode replaces both --&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">html</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> class</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;analyzer&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><ul><li><code>.dark</code> selects the dark token set</li><li><code>data-theme=&quot;&lt;accent&gt;&quot;</code> overrides <code>--primary</code> and <code>--ring</code></li><li><code>.analyzer</code> overrides the whole palette and takes priority over both</li></ul><p>The accent rules are written as <code>[data-theme=&quot;blue&quot;]:not(.analyzer)</code> precisely so that Analyzer Mode cannot be recoloured.</p><h4 id="storage-and-persistence" tabindex="-1">Storage and persistence <a class="header-anchor" href="#storage-and-persistence" aria-label="Permalink to &quot;Storage and persistence&quot;">​</a></h4><p>The Zustand store persists to <code>localStorage</code> under the key <code>tradeboard-theme</code>:</p><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">JSON</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">parse</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(localStorage.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">getItem</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;tradeboard-theme&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">))</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// { state: { mode: &#39;dark&#39;, color: &#39;blue&#39;, appMode: &#39;live&#39; }, version: 0 }</span></span></code></pre></div><p>Analyzer mode itself is server state, not a browser preference: toggling it posts to <code>/auth/analyzer-toggle</code> with a CSRF token, and the frontend re-syncs the value from the backend on load.</p><h4 id="theme-colour-tokens" tabindex="-1">Theme colour tokens <a class="header-anchor" href="#theme-colour-tokens" aria-label="Permalink to &quot;Theme colour tokens&quot;">​</a></h4><p>Each mode defines the same semantic tokens, so components never hardcode a colour:</p><table tabindex="0"><thead><tr><th>Token</th><th>Purpose</th><th>Examples</th></tr></thead><tbody><tr><td><code>--primary</code></td><td>Accent colour</td><td>Buttons, links, active states</td></tr><tr><td><code>--primary-foreground</code></td><td>Text on accent</td><td>Button labels</td></tr><tr><td><code>--background</code></td><td>Page background</td><td>App shell</td></tr><tr><td><code>--foreground</code></td><td>Body text</td><td>Labels, paragraphs</td></tr><tr><td><code>--card</code></td><td>Raised surface</td><td>Cards, panels</td></tr><tr><td><code>--popover</code></td><td>Overlay surface</td><td>Dropdowns, dialogs</td></tr><tr><td><code>--secondary</code></td><td>Supporting surface</td><td>Secondary buttons</td></tr><tr><td><code>--muted</code></td><td>Subdued surface</td><td>Disabled states, placeholders</td></tr><tr><td><code>--accent</code></td><td>Highlight surface</td><td>Hover states</td></tr><tr><td><code>--destructive</code></td><td>Error states</td><td>Loss, failed orders</td></tr><tr><td><code>--border</code> / <code>--input</code></td><td>Borders</td><td>Dividers, input outlines</td></tr><tr><td><code>--ring</code></td><td>Focus ring</td><td>Keyboard focus</td></tr></tbody></table><p>Colours are authored in OKLCH, which keeps perceived lightness consistent when an accent is swapped.</p><h3 id="browser-compatibility" tabindex="-1">Browser compatibility <a class="header-anchor" href="#browser-compatibility" aria-label="Permalink to &quot;Browser compatibility&quot;">​</a></h3><p>Tradeboard&#39;s themes work in all current browsers:</p><ul><li>Chrome/Edge 111+</li><li>Firefox 113+</li><li>Safari 15.4+</li><li>Modern mobile browsers (iOS Safari, Chrome Mobile)</li></ul><p>OKLCH colours and the Tailwind 4 engine need these versions. Internet Explorer is not supported.</p><h3 id="rebuilding-the-frontend-advanced" tabindex="-1">Rebuilding the frontend (advanced) <a class="header-anchor" href="#rebuilding-the-frontend-advanced" aria-label="Permalink to &quot;Rebuilding the frontend (advanced)&quot;">​</a></h3><p>You do not need Node.js to run Tradeboard. The repository ships the built bundle in <code>frontend/dist</code>, and the Docker image rebuilds it as part of the image build.</p><p>If you want to change the theme tokens yourself, edit <code>frontend/src/index.css</code> and rebuild:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> frontend</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ci</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span></code></pre></div><p>This requires Node.js 20.20+, 22.22+ or 24.13+ (the range declared in <code>frontend/package.json</code>). <code>npm run dev</code> starts the Vite dev server if you would rather iterate with hot reload.</p><p>To add a new accent colour you need to touch three places:</p><ol><li><code>ThemeColor</code> in <code>frontend/src/stores/themeStore.ts</code></li><li><code>ACCENT_COLORS</code> in <code>frontend/src/pages/Profile.tsx</code></li><li>A <code>[data-theme=&quot;&lt;name&gt;&quot;]:not(.analyzer)</code> block, and its <code>.dark</code> counterpart, in <code>frontend/src/index.css</code></li></ol><h3 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h3><h4 id="theme-not-changing" tabindex="-1">Theme not changing <a class="header-anchor" href="#theme-not-changing" aria-label="Permalink to &quot;Theme not changing&quot;">​</a></h4><ol><li><strong>Clear browser cache</strong>: hard reload with <code>Ctrl+Shift+R</code> (Windows/Linux) or <code>Cmd+Shift+R</code> (Mac)</li><li><strong>Check localStorage</strong>: DevTools, Application, Local Storage, look for the <code>tradeboard-theme</code> key</li><li><strong>Disable browser extensions</strong>: some extensions rewrite page styles</li><li><strong>Try a private window</strong>: rules out extension conflicts</li></ol><h4 id="analyzer-mode-theme-will-not-change" tabindex="-1">Analyzer mode theme will not change <a class="header-anchor" href="#analyzer-mode-theme-will-not-change" aria-label="Permalink to &quot;Analyzer mode theme will not change&quot;">​</a></h4><p>This is <strong>expected behaviour</strong>. The purple Analyzer palette is locked for safety. To change themes:</p><ol><li>Leave Analyzer Mode</li><li>Return to Live Mode</li><li>Select your preferred mode and accent</li><li>They are restored automatically the next time you leave Analyzer Mode</li></ol><h4 id="a-custom-accent-does-not-appear" tabindex="-1">A custom accent does not appear <a class="header-anchor" href="#a-custom-accent-does-not-appear" aria-label="Permalink to &quot;A custom accent does not appear&quot;">​</a></h4><ol><li>Confirm you added the colour in all three places listed above</li><li>Rebuild the frontend: <code>cd frontend &amp;&amp; npm run build</code></li><li>Hard reload the browser so the new bundle is fetched</li></ol><h3 id="credits-and-acknowledgments" tabindex="-1">Credits and acknowledgments <a class="header-anchor" href="#credits-and-acknowledgments" aria-label="Permalink to &quot;Credits and acknowledgments&quot;">​</a></h3><h4 id="tailwind-css" tabindex="-1">Tailwind CSS <a class="header-anchor" href="#tailwind-css" aria-label="Permalink to &quot;Tailwind CSS&quot;">​</a></h4><p>Thanks to <a href="https://tailwindcss.com/" target="_blank" rel="noreferrer"><strong>Tailwind Labs</strong></a> for the utility-first CSS framework that forms the foundation of the design system.</p><ul><li><strong>Project</strong>: <a href="https://github.com/tailwindlabs/tailwindcss" target="_blank" rel="noreferrer">github.com/tailwindlabs/tailwindcss</a></li><li><strong>License</strong>: MIT</li></ul><h4 id="radix-ui" tabindex="-1">Radix UI <a class="header-anchor" href="#radix-ui" aria-label="Permalink to &quot;Radix UI&quot;">​</a></h4><p>Thanks to the <a href="https://www.radix-ui.com/" target="_blank" rel="noreferrer"><strong>Radix</strong></a> team for the accessible, unstyled component primitives underneath Tradeboard&#39;s UI.</p><ul><li><strong>License</strong>: MIT</li></ul><h4 id="community" tabindex="-1">Community <a class="header-anchor" href="#community" aria-label="Permalink to &quot;Community&quot;">​</a></h4><p>Special thanks to the Tradeboard community for feedback on themes, accessibility improvements, and user experience suggestions.</p><h3 id="resources" tabindex="-1">Resources <a class="header-anchor" href="#resources" aria-label="Permalink to &quot;Resources&quot;">​</a></h3><h4 id="official-documentation" tabindex="-1">Official documentation <a class="header-anchor" href="#official-documentation" aria-label="Permalink to &quot;Official documentation&quot;">​</a></h4><ul><li><strong>Tailwind CSS</strong>: <a href="https://tailwindcss.com/docs" target="_blank" rel="noreferrer">tailwindcss.com/docs</a></li><li><strong>Radix UI</strong>: <a href="https://www.radix-ui.com/primitives" target="_blank" rel="noreferrer">radix-ui.com/primitives</a></li></ul><h4 id="tradeboard-documentation" tabindex="-1">Tradeboard documentation <a class="header-anchor" href="#tradeboard-documentation" aria-label="Permalink to &quot;Tradeboard documentation&quot;">​</a></h4><ul><li><strong>Getting Started</strong>: <a href="https://docs.algo.wesoftcorp.com/getting-started" target="_blank" rel="noreferrer">docs.algo.wesoftcorp.com/getting-started</a></li></ul>`,86)])])}const m=t(s,[["render",n]]);export{u as __pageData,m as default};
